export const RUSSIAN_B1_LESSONS: readonly LearningLesson[] = seeds.map(seed => {
  const lessonId = `ru-b1-${seed.id}`;
  const sentences = seed.rows.map(([text, fa, pronunciation, word, meaning, pattern], i) =>
    everydaySentence(`${lessonId}-${String(i + 1).padStart(2, '0')}`, text, fa, pronunciation, [[word, meaning]], pattern ?? (i === 0 ? seed.pattern : undefined)));
  // Two formative recognition questions use actual lesson examples; no CEFR
  // proficiency or independent writing/speaking result is inferred from them.
  const selected = ['reflexive-imperative', 'services-complaints'].includes(seed.id) ? [6, 0, 2] : [3, 5, 7];
  const choices = selected.map(index => seed.rows[index][0]);
  // Stable across future lesson reordering: saved quiz selections are indices.
  const choiceSeed = [...seed.id].reduce((sum, char) => sum + char.charCodeAt(0), 0);
  const answerIndex = choiceSeed % choices.length;
  // Rotate the answer's position without changing the other alternatives.
  const [answer] = choices.splice(0, 1);
  choices.splice(answerIndex, 0, answer);
  const focus = focusChecks[seed.id];
  const focusChoices = [...focus.choices];
  const [focusAnswer] = focusChoices.splice(focus.correctIndex, 1);
  const focusIndex = (choiceSeed + 1) % 3;
  // Vary the position while preserving the authored explanation and answer.
  focusChoices.splice(focusIndex, 0, focusAnswer);
  const checks = [{ ...focus, choices: focusChoices, correctIndex: focusIndex }, {
    promptFa: `کدام جمله یعنی «${seed.rows[selected[0]][1]}»؟`,
    choices,
    correctIndex: answerIndex,
    explanationFa: `پاسخ نمونه: ${seed.rows[selected[0]][0]} — ${seed.rows[selected[0]][1]}`,
  }];
  return everydayLesson(lessonId, seed.title, seed.situation, sentences,
    seed.dialogue.map(([speaker, text, fa]) => ({ speaker, text, fa })), checks, seed.note);
});
